 "content": "def transform(grid):
    """Copy the colored motif into every zero-pattern occurrence."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            if value not in (0,):
                counts[value] = counts.get(value, 0) + 1
    # The motif color is the least frequent nonzero color, unlike the field.
    color = min(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    min_r = min(r for r, c in points)
    max_r = max(r for r, c in points)
    min_c = min(c for r, c in points)
    max_c = max(c for r, c in points)
    shape = [(r - min_r, c - min_c) for r, c in points]
    for top in range(h - (max_r - min_r + 1) + 1):
        for left in range(w - (max_c - min_c + 1) + 1):
            if all(grid[top + dr][left + dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[top + dr][left + dc] = color
    return out
